#!/usr/bin/env python3
"""Официальный SVG-план ПИР 13–15: интерактивные метки, очередь, посещения."""
import json, pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
PLANS=json.loads((ROOT/'pir-expo/plan/plan.json').read_text())
HTML=r'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="robots" content="noindex,nofollow"><title>ПИР Экспо · официальный план и маршрут</title>
<style>:root{--y:#fdd101;--a:#2fbf5b;--b:#38b6f5;--c:#f28c28;--v:#a259ff}*{box-sizing:border-box}body{margin:0;background:#000;color:#eee;font:15px/1.45 Arial,sans-serif}a{color:var(--y)}button{cursor:pointer}header{position:sticky;top:0;background:#070707;z-index:20;border-bottom:1px solid #333}.inner,main{max-width:1100px;margin:auto;padding:10px 16px}.brand{color:var(--y);font-weight:800;display:flex;align-items:center;gap:9px}.brand a{margin-left:auto;font-weight:400}.sg{background:white;border:4px solid var(--y);color:#000;width:26px;height:26px;text-align:center;line-height:18px}h1{font-size:19px;margin:8px 0}.chips{display:flex;gap:6px;flex-wrap:wrap;margin:7px 0}.chip{background:#242424;border:1px solid #555;border-radius:16px;color:#fff;padding:7px 11px}.chip.on{background:var(--y);color:#000;border-color:var(--y);font-weight:bold}.search{width:100%;padding:10px;border-radius:8px;border:1px solid #666;background:#111;color:#fff;font-size:16px}.hits{max-height:28vh;overflow:auto}.hit{display:block;width:100%;text-align:left;padding:10px;background:#222;border:0;border-bottom:1px solid #555;color:#fff}.hit b{color:var(--y)}.bar{display:flex;align-items:center;color:#aaa}.zoom{margin-left:auto}.zoom button{background:#222;border:1px solid #555;color:#fff;border-radius:7px;font-size:20px;padding:3px 12px}.viewport{height:min(67vh,760px);overflow:auto;background:#eee;border:1px solid #555;border-radius:10px;margin:8px 0}.floor{position:relative;width:624px}.floor img{display:block;width:100%;height:auto}.mk{position:absolute;transform:translate(-50%,-50%);background:var(--a);border:2px solid #111;border-radius:12px;min-width:19px;height:19px;padding:0 3px;color:#000;font:800 11px/15px Arial;box-shadow:0 0 2px #fff}.mk.B{background:var(--b)}.mk.C{background:var(--c)}.mk.seen{background:var(--v);color:#fff}.mk.sel{outline:3px solid #f35;z-index:5}.legend,.note{color:#aaa;font-size:13px}.dot{display:inline-block;width:11px;height:11px;border-radius:50%;margin:0 3px 0 9px}h2{font-size:18px}.route{padding:0;list-style:none}.route li{display:flex;gap:10px;align-items:center;background:#171717;border-radius:9px;margin:6px 0;padding:10px;cursor:pointer}.route .nm{flex:1}.route .st{color:var(--y);font-weight:bold;min-width:60px}.route .seen .nm{text-decoration:line-through;color:#aaa}.drawer{position:fixed;bottom:0;left:0;right:0;max-height:60vh;overflow:auto;background:#111;border-top:2px solid var(--y);z-index:50;padding:16px;display:none}.drawer.on{display:block}.drawer .x{float:right;background:none;border:0;color:#fff;font-size:27px}.detail{max-width:800px;margin:9px auto;padding:8px 12px;border:1px solid #444;border-radius:10px}.go{display:inline-block;background:var(--y);color:#000;text-decoration:none;border-radius:8px;padding:9px;margin:8px 0;font-weight:bold}@media(max-width:700px){.viewport{height:57vh}.inner,main{padding:8px 12px}}</style></head><body>
<header><div class="inner"><div class="brand"><span class="sg">Ц</span>ПИР ЭКСПО · ПЛАН <a href="presenter.html">Опросник →</a></div><h1>Официальный план с метками Click Out</h1><div class="chips" id="halls"></div><div class="chips" id="filters"></div><input id="q" class="search" placeholder="Компания или номер стенда" autocomplete="off"><div class="hits" id="hits"></div></div></header>
<main><div class="bar"><span id="cnt">Загружаю…</span><span class="zoom"><button id="minus" aria-label="Уменьшить">−</button> <button id="plus" aria-label="Увеличить">+</button></span></div><div class="viewport" id="viewport"><div class="floor" id="floor"><img id="img" alt="План зала"></div></div><p class="legend"><span class="dot" style="background:var(--a)"></span>A: сети и бренды <span class="dot" style="background:var(--b)"></span>B: проверить <span class="dot" style="background:var(--c)"></span>C: остальные <span class="dot" style="background:var(--v)"></span>уже опрошено</p><h2>Очередь обхода</h2><p class="note">На схеме — реальные контуры стендов организатора. Метки A/B/C — приоритеты Церебро; после отправки опроса стенд становится фиолетовым.</p><ol id="route" class="route"></ol><p class="note">Источник: <a href="https://pirexpo.com/map/15" target="_blank" rel="noopener">официальный план PIR Expo 2026</a>. Снимок 25.10.2026. Ненайденным на плане стендам координаты не выдуманы.</p></main><div class="drawer" id="drawer"><button class="x" id="close" aria-label="Закрыть">×</button><div id="details"></div></div>
<script>
const PLAN=__PLAN__,SRC='ПИР Экспо',CSV='https://docs.google.com/spreadsheets/d/1BPelyLKYCGHItz3HPlcjZG_9Qur1SiKT9ee7SnwMPUs/gviz/tq?tqx=out:csv&sheet='+encodeURIComponent('Ответы')+'&tq='+encodeURIComponent('select B,D,V');
const $=id=>document.getElementById(id),esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const HOMO={'А':'A','В':'B','С':'C','Е':'E','Н':'H','К':'K','М':'M','О':'O','Р':'P','Т':'T','Х':'X'},stand=s=>String(s||'').toUpperCase().replace(/[АВСЕНКМОРТХ]/g,c=>HOMO[c]).split(',')[0].replace(/[^A-Z0-9]/g,''),norm=s=>String(s||'').toLowerCase().replace(/ё/g,'е').replace(/[^a-zа-я0-9]/g,''),dom=s=>String(s||'').toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').split(/[/?#]/)[0];
let R=[],N=new Set(),D=new Set(),H='15',T=new Set(['A','B']),F='all',Z=innerWidth<700?1.8:1.25,SEL=null;
function visits(){try{return JSON.parse(localStorage.getItem('expo_visits')||'[]')}catch(e){return []}}
function add(v){if(!String(v.source||'').toLowerCase().includes(SRC.toLowerCase()))return;N.add(norm(v.client));if(v.site)D.add(dom(v.site))}
function seen(r){return N.has(norm(r.name))||!!r.site&&D.has(dom(r.site))}
function csv(t){let o=[],r=[],v='',q=false;for(let i=0;i<t.length;i++){let c=t[i];if(c==='"'){if(q&&t[i+1]==='"'){v+='"';i++}else q=!q}else if(c===','&&!q){r.push(v);v=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&t[i+1]==='\n')i++;r.push(v);o.push(r);r=[];v=''}else v+=c}if(v||r.length){r.push(v);o.push(r)}return o}
async function sync(){N.clear();D.clear();visits().forEach(add);try{const r=await fetch(CSV,{cache:'no-store'});if(r.ok)csv(await r.text()).slice(1).forEach(v=>add({client:v[0],site:v[1],source:v[2]}))}catch(e){}render()}
function point(r){return PLAN[r.hall]?.stands[stand(r.stand)]}
function keep(r){return r.hall===H&&T.has(r.prio)&&(F==='all'||F==='direct'&&r.tags.includes('прямой заказ/бронь')||F==='brand'&&r.tags.includes('брендформанс'))}
function controls(){$('halls').innerHTML=Object.keys(PLAN).map(h=>`<button class="chip ${h===H?'on':''}" data-h="${h}">Зал ${h}</button>`).join('');$('filters').innerHTML=[['all','Все'],['direct','Сети'],['brand','Бренды']].map(([v,l])=>`<button class="chip ${v===F?'on':''}" data-f="${v}">${l}</button>`).join('')+['A','B','C'].map(v=>`<button class="chip ${T.has(v)?'on':''}" data-t="${v}">${v}</button>`).join('')}
function render(){if(!R.length)return;controls();let p=PLAN[H],floor=$('floor');floor.style.width=p.w*Z+'px';$('img').src='plan/'+p.img;$('img').alt='Официальный план зала '+H;let rr=R.filter(r=>keep(r)&&point(r)),groups=new Map();for(let r of rr){let k=stand(r.stand);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(r)}floor.querySelectorAll('.mk').forEach(x=>x.remove());for(let [k,g] of groups){let v=p.stands[k],best=g.find(x=>x.prio==='A')||g.find(x=>x.prio==='B')||g[0],b=document.createElement('button');b.className='mk '+best.prio+(g.some(seen)?' seen':'')+(SEL&&g.some(x=>x.id===SEL.id)?' sel':'');b.style.left=v[0]+'%';b.style.top=v[1]+'%';b.dataset.stand=k;b.textContent=g.length>1?g.length:best.top?'★':'•';b.title=g.map(x=>x.name).join(', ')+' · '+k;floor.append(b)}let order=rr.sort((a,b)=>Number(seen(a))-Number(seen(b))||Number(b.top)-Number(a.top)||'ABC'.indexOf(a.prio)-'ABC'.indexOf(b.prio)||point(a)[1]-point(b)[1]||point(a)[0]-point(b)[0]);$('cnt').textContent=`Зал ${H}: ${rr.length} компаний, ${groups.size} стендов · ${rr.filter(seen).length} опрошено`;$('route').innerHTML=order.slice(0,100).map(r=>`<li data-id="${r.id}" class="${seen(r)?'seen':''}"><span class="st">${esc(r.stand)}</span><span class="nm">${r.top?'★ ':''}${esc(r.name)}</span>${r.prio}</li>`).join('')||'<li>Для этого фильтра стендов нет.</li>'}
function card(rr){$('details').innerHTML=rr.map(r=>`<div class="detail"><h2>${esc(r.name)} ${r.top?'★':''}</h2><p>Зал ${r.hall} · стенд ${esc(r.stand)} · эшелон ${r.prio}${seen(r)?' · уже опрошен':''}</p><p>${esc(r.meta)}</p><p>${esc(r.profile.join(', '))}</p>${r.site?`<a href="${esc(r.site)}" target="_blank" rel="noopener">Сайт ↗</a><br>`:''}<a class="go" href="presenter.html?c=${encodeURIComponent(r.name)}&s=${encodeURIComponent(r.stand)}">Опрос по этой компании →</a></div>`).join('');$('drawer').classList.add('on')}
function open(r){if(!r)return;SEL=r;H=r.hall;if(!T.has(r.prio))T.add(r.prio);if(F==='direct'&&!r.tags.includes('прямой заказ/бронь')||F==='brand'&&!r.tags.includes('брендформанс'))F='all';render();let pt=point(r);if(pt){let v=$('viewport'),f=$('floor');v.scrollLeft=Math.max(0,f.clientWidth*pt[0]/100-v.clientWidth/2);v.scrollTop=Math.max(0,f.clientHeight*pt[1]/100-v.clientHeight/2)}card([r])}
$('halls').onclick=e=>{let b=e.target.closest('[data-h]');if(b){H=b.dataset.h;localStorage.setItem('pir_map_hall',H);SEL=null;render();$('viewport').scrollTo(0,0)}};$('filters').onclick=e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.t){T.has(b.dataset.t)?T.delete(b.dataset.t):T.add(b.dataset.t)}else F=b.dataset.f;render()};$('floor').onclick=e=>{let b=e.target.closest('.mk');if(b)card(R.filter(r=>r.hall===H&&stand(r.stand)===b.dataset.stand))};$('route').onclick=e=>{let b=e.target.closest('[data-id]');if(b)open(R.find(r=>r.id==b.dataset.id))};$('hits').onclick=e=>{let b=e.target.closest('[data-id]');if(!b)return;let r=R.find(x=>x.id==b.dataset.id);$('q').value=r.name;$('hits').innerHTML='';open(r)};$('q').oninput=e=>{let q=norm(e.target.value);$('hits').innerHTML=q?R.filter(r=>norm(r.name+' '+r.stand+' '+r.profile.join(' ')).includes(q)).slice(0,8).map(r=>`<button class="hit" data-id="${r.id}"><b>${esc(r.stand||'—')}</b> · ${esc(r.name)} · зал ${r.hall||'?'}</button>`).join(''):''};$('close').onclick=()=>$('drawer').classList.remove('on');$('minus').onclick=()=>{Z=Math.max(.8,+(Z-.25).toFixed(2));render()};$('plus').onclick=()=>{Z=Math.min(3.5,+(Z+.25).toFixed(2));render()};window.addEventListener('storage',sync);document.addEventListener('visibilitychange',()=>{if(!document.hidden)sync()});
fetch('exhibitors.json').then(r=>r.json()).then(d=>{R=d;H=localStorage.getItem('pir_map_hall')||'15';if(!PLAN[H])H='15';render();sync()}).catch(()=>{$('cnt').textContent='Не удалось загрузить каталог.'});
</script></body></html>'''
out=ROOT/'pir-expo/map.html';out.write_text(HTML.replace('__PLAN__',json.dumps(PLANS,ensure_ascii=False).replace('</','<\\/')),encoding='utf-8')
print('OK',out,'official halls',len(PLANS),'labels',sum(len(x['stands']) for x in PLANS.values()))
